"""Keep the main gallery limited to current full-municipality deliverables."""
from pathlib import Path
import json,html,shutil
from restore_geoai_explanations import render_geoai_explanations
import pandas as pd,geopandas as gpd
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
ROOT=Path(__file__).resolve().parents[1];DEST=ROOT/'netlify_site/src';OUT=ROOT/'output/plano_city/public'
def run():
 OUT.mkdir(exist_ok=True);old=DEST/'gallery.html';archive=DEST/'gallery-archive.html'
 if old.exists() and not archive.exists():archive.write_text(old.read_text().replace('<h1>Map Gallery</h1>','<h1>Archived working maps</h1><p><a href="gallery.html">Current municipal gallery →</a></p><p>Historical figures and earlier comparison profiles. Scope and dates vary by figure.</p>'))
 b=gpd.read_file(ROOT/'output/plano_city/accessibility/block_accessibility.gpkg');d=pd.read_csv(ROOT/'output/plano_city/accessibility/nearest_category_costs.csv',dtype={'GEOID20':str});p=d.pivot(index='GEOID20',columns='category',values='min_friction_equivalent_minutes');means=p.mean(axis=1).where(p.notna().all(axis=1));b['family_cost']=b.GEOID20.map(means);valid=b.family_cost.notna()&b.HU100.gt(0)&b.access_snap_gap_m.le(100)
 fig,ax=plt.subplots(figsize=(12,8));b.plot(ax=ax,color='#dce1dd',linewidth=0);lo,hi=b.loc[valid,'family_cost'].quantile([.02,.98]);b.loc[valid].plot(ax=ax,column='family_cost',cmap='RdYlBu_r',vmin=lo,vmax=hi,linewidth=0,legend=True,legend_kwds={'label':'Average modeled trip effort (equivalent minutes)','shrink':.7});ax.set_title('Plano · walking access across all destination categories');ax.set_axis_off();fig.text(.04,.025,'Full municipal origin scope; no trip budget. Blue = lower, red = higher mean nearest-category route cost.\nGray = no 2020 housing, incomplete access or connection-distance review. Longer trips can be extent-sensitive.\nSources: OpenStreetMap contributors; Census Bureau; City of Plano; TxDOT; USDA NAIP; USGS Landsat.',fontsize=9);fig.tight_layout(rect=[0,.1,1,1]);fig.savefig(OUT/'plano_family_access.png',dpi=170);plt.close(fig);shutil.copy2(OUT/'plano_family_access.png',DEST/'figures/plano_family_access.png')
 rows=[('plano_family_access.png','Shade-priority walking access','All available destination categories. Full municipal scope.'),('plano_ai_tree_paths.png','GeoAI tree adjacency · walking paths','AI tree raster sampled beside vector paths. This feature enters the routing cost.'),('plano_ai_tree_cover.png','GeoAI canopy summary · census blocks','GeoAI predicts trees from 2022 aerial imagery. Nearby tree cover informs each walking-edge cost; it is a shade proxy, not measured shade.'),('plano_surface_temperature.png','Summer surface temperature','Clear-sky summer 2025 Landsat composite. Surface temperature, not air temperature.'),('plano_traffic_burden.png','Traffic volume','Nearby mapped TxDOT AADT, normalized against Plano. Not a crash-risk measure.'),('plano_context_population_density.png','Population density','2020 Census residents per land km². Full-block values; city-border fragments flagged in the master map.'),('plano_context_median_gross_rent.png','Area median rent','2020–2024 ACS block-group estimates. Not current listings.'),('plano_context_median_home_value.png','Area median home value','2020–2024 ACS owner-reported values. Not individual appraisals.'),('plano_weighted_network.png','Weighted walking network','Actual mapped edges, with environmental context. Routes extend 3 km beyond Plano.')]
 rows=[('distance_vs_friction_maps.png','Friction versus walking time','Same graph, destinations and origins. Matched cost-percentile scales.'),('friction_rank_change.png','Where rankings change','Friction cost percentile minus time-only percentile. Blue improves; red worsens.'),('distance_friction_scatter.png','Does friction reproduce distance?','All-category comparison. Differences show model behavior, not validated human preferences.')]+rows
 cards=''.join('<figure><h2>'+html.escape(title)+'</h2><a href="figures/'+image+'" target="_blank"><img src="figures/'+image+'" alt="'+html.escape(title)+' across the Plano municipal area" loading="lazy"></a><figcaption>'+html.escape(caption)+'</figcaption><a class="small" href="figures/'+image+'" download>Download PNG</a></figure>' for image,title,caption in rows)
 page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>EmPath · Current Plano maps</title><link rel="stylesheet" href="site.css"></head><body><header class="topbar"><a class="wordmark" href="index.html">EmPath</a><nav><a href="app.html">Explorer</a><a href="master-map.html">Master map</a><a href="behind.html">Behind the scores</a></nav></header><main class="content"><h1>The useful maps.<br>In one place.</h1><section class="gallery-master"><h2>Master interactive map</h2><p>Explore the cleaned layers together: census blocks and addresses, GeoAI tree cover, heat, traffic, walking paths, population and housing.</p><iframe class="master-map-embed" src="master-map.html?embedded=1" title="Master interactive map: environmental, walking, population and housing layers" loading="lazy"></iframe><h3>Where GeoAI enters the tool</h3><p>A pretrained model identifies trees in aerial imagery. We measure predicted tree cover beside each path, then use it in the friction equation.</p><a href="behind.html">See the imagery → predictions → routes workflow ↗</a></section>'''+render_geoai_explanations()+'''<div class="gallery-grid">'''+cards+'''</div><p class="archive-note"><a href="gallery-archive.html">Earlier experiments and four-ZIP maps are archived here.</a></p></main><script src="journey.js"></script></body></html>'''
 (DEST/'gallery.html').write_text(page);(OUT/'relevant_gallery.json').write_text(json.dumps([{'image':i,'title':t,'caption':c} for i,t,c in rows],indent=2));print('Current municipal gallery:',len(rows),'maps; earlier figures retained in archive.')
